-- aar/w3/aar_row_661_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 661 (the Shared Library header comment set to the library body) and its ask_aar_builders row.
-- Every value is from Wall 12265 to 12273 (each read whole by W3), W4's card and press record (read by W3 in W4's thread by message id), audit_log row 42475 (title and first 200 characters read by W3), and md5sum by W3 of the files named.
-- NOT READ by W3: the live engine and n8n; the write script's text; W1's files. md5_written is the md5 of the written Shared Library jsCode as W1 stated it in full (Wall 12269, 12271); no whole target file is stored, because the write built its target from a fetch taken in the same call.
-- objective_met is 'in part': written and read back; the run-start check passes; no run since the write.
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (661, '0', $t$ASK 661: the Shared Library header comment is set to the library body, so the engine's Library Check lets a run start$t$,
  $t$The run-start check refused at 18:14 CST 2026-11-25 on engine 5d43650d (Wall 12265): the Shared Library header comment named "library sha 0f8a6b2950f7de68, 3859 lines" while the body was fb8658437cad8fbf, 3,910 lines. The engine's own Library Check node, after Debate Start, stops a webhook run with "pkgLIB2: Shared Library text sha ... differs" when the two differ, so the next run would have stopped at its first step. Change, one node (Shared Library), the header comment only: "library sha 0f8a6b2950f7de68, 3859 lines" becomes "library sha fb8658437cad8fbf, 3910 lines". Expected effect: the Library Check passes and the next run starts. Standing rule from the coordinator (18:24 CST): every engine write script checks the Shared Library header against the body before it writes and refuses on a mismatch. Not changed: any other node, the child, the database, a model setting, reasoning.$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write it live" at 18:29 CST 2026-11-25 on W4's card (Wall 12270; audit 42475), engine 5d43650d to 66ba992d (426 nodes; the child aad0ad9c unchanged by W4's post), and read back MATCH by W1 (Wall 12271: 426 of 426 nodes equal to W1's rebuild, connections equal; against 5d43650d only the Shared Library differs; the header reads "library sha fb8658437cad8fbf, 3910 lines" and the body hashes to the same with 3,910 lines; headerParameters present on all 61 nodes; standing 31 PASS 0 FAIL; the child not checked by W1). After the readback W4's run-start check on 66ba992d gave GO (W4's message to the coordinator, 18:33 CST; not posted on the Wall). First build graded FAIL F1 by W1 (Wall 12266): its base was a saved fetch with headerParameters stripped, and written whole it would have removed the request headers of 61 nodes; rebuilt from a fresh live fetch (Wall 12268) and regraded PASS WITH N1 (Wall 12269; N1: W4's target file was not on the shared folder, so W1 compared the jsCode md5; the write rebuilds from a fetch in the same call). CAUSE AND MISTAKES: W1's stored fetches show the header stale on every live version from 393bca2e (ASK 641) through 5d43650d (ASK 654) (Wall 12267); no run started in that span, so the engine never threw. W4: its write scripts checked the pair Library Check and the standing set, not the header against the body (Wall 12265). W1: every build grade and readback in that span missed it, and at the ASK 654 grade it was listed as a harmless defect without reading Library Check (Wall 12266, 12267). W4 at the write: the script's final pair check used a relative path and failed to open its file after the PUT; rerun with full paths, PASSES, script fixed (Wall 12270). IN PART, because no run has been made since the write. NOT CHECKED by W3: the live engine; the write script's text; audit 42475 beyond its title and first 200 characters.$t$,
  '12265, 12266, 12267, 12268, 12269, 12270, 12271, 12273',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo586rdt9SWY33g6hgMB54AW5g, "Write the ASK 661 library header fix live so the next run can start?"): he pressed "Write it live" at 18:29 CST 2026-11-25. The card and the press record were read by W3 in W4's thread; the press time is from the coordinator's message to W4 and Wall 12270.$t$::text),
  $j${"answer": "Write it live", "question": "Write the ASK 661 library header fix live so the next run can start?", "options": {"Write it live": "W4 writes the one header line on engine 5d43650d, W1 reads it back, W4 reruns the start check and posts GO, then you launch.", "Hold": "Nothing is written; the next run stops at Library Check."}, "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo586rdt9SWY33g6hgMB54AW5g", "press_time": "18:29 CST 2026-11-25", "source": "the card and the press record read by W3 in W4's thread by message id; press time from the coordinator's message to W4 (00:29Z) and Wall 12270; the message above the card not read by W3."}$j$::jsonb,
  'W4',
  $j${"md5": null, "path": null, "note": "no plan file: the fault, the fix and its tests were posted for review on Wall 12265 and the rebuild on Wall 12268; graded by W1 (Wall 12266 FAIL F1, Wall 12269 PASS WITH N1).", "source": "Wall 12265, 12266, 12268, 12269"}$j$::jsonb,
  $j$[{"path": "ask661/w4/b661.cjs", "md5": "86a4bd4aa160b34ec66d05c36c8c6e6f", "what": "build script (changes only the header comment)"}, {"path": "ask661/w4/t661.cjs", "md5": "9fed38fbc2a4adaea4e6cb78dfc42cd3", "what": "test (runs the engine's own Library Check code)"}, {"path": "ask661/w4/write/write661.sh", "md5": "b9f615992dbf250b4f899b0a2745d8ff", "what": "write script with the header-versus-body check; builds the target from a fetch taken in the same call"}, {"path": "ask661/w4/write/build.txt", "md5": "5730e3bbbb95a995a79b919ba7362313", "what": "build output of the write"}, {"path": "ask661/w4/write/standing.txt", "md5": "25e8000a359ad7ab436a5a8befdfeefb", "what": "standing set output"}, {"path": "ask661/w4/write/fetchback_eng_661.json", "md5": "5deebf4185a057ca52fb39752b161900", "what": "fetch-back after the write"}, {"path": "ask661/w4/write/putreply_eng.json", "md5": "d915d2a2ceab7c7d97d92b3e9f9a7326", "what": "PUT reply"}]$j$::jsonb,
  $j${"engine": "ask661/w4/write/revert_eng_661.json, md5 369e3b2579006d28723869d65e136775 (restores 5d43650d by W4's post; that version's header is stale and its Library Check refuses a run)", "child": "not written; nothing to revert", "database": "not written; nothing to revert", "rehearsed": "not stated in the posts W3 read", "source": "Wall 12270; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "FAIL F1 (first build, target 393e79c6, base with headerParameters stripped), replaced by the regrade", "wall_id": 12266, "md5_graded": "393e79c6", "verdict_norm": "FAIL", "source": "Wall 12266"}, {"seat": "W1", "verdict": "PASS WITH N1 (rebuild from a fresh live fetch; Shared Library jsCode md5 stated in full)", "wall_id": 12269, "md5_graded": "1fb510f18248e24039c29c231506f06a", "verdict_norm": "PASS", "source": "Wall 12269"}]$j$::jsonb,
  ARRAY['1fb510f18248e24039c29c231506f06a'], '[42475]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, node Shared Library (header comment only)", "before": "version 5d43650d; header \"library sha 0f8a6b2950f7de68, 3859 lines\"; body fb8658437cad8fbf, 3,910 lines", "after": "version 66ba992d-58b5-4dd8-8ca4-85bbfe79e447, 426 nodes; header \"library sha fb8658437cad8fbf, 3910 lines\"; body unchanged; Shared Library jsCode md5 1fb510f18248e24039c29c231506f06a; headerParameters identical on all 61 nodes"}]$j$::jsonb,
  $j$[{"name": "t661.cjs", "result": "4 PASS, 0 FAIL, running the engine's own Library Check code: the base fails, the target passes; only Shared Library differs; connections equal", "source": "Wall 12265, 12268, 12270"}, {"name": "header-versus-body check in write661.sh", "result": "passed before the PUT (fb8658437cad8fbf, 3910); W4 states it refuses the engine as it was before the write", "source": "Wall 12270; W4's message in its thread, 18:26 CST"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W1, Wall 12269), at the write (W4, Wall 12270) and on live (W1, Wall 12271); pair check PASSES after a rerun with full paths", "source": "Wall 12269, 12270, 12271"}, {"name": "run-start check on 66ba992d", "result": "exit 0, GO, all checks ok (body of run 42528's seats)", "source": "W4's message to the coordinator, 18:33 CST, read by W3 in W4's thread; output run_next/w4/runstart_661.txt not read by W3"}, {"name": "NOT RUN", "result": "any live call", "source": "Wall 12270"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (fresh fetch of 66ba992d: 426 of 426 nodes equal to W1's rebuild, connections equal; only Shared Library differs from 5d43650d; header equals the body sha and line count; jsCode md5 1fb510f18248e24039c29c231506f06a; headerParameters on all 61 nodes; standing 31 PASS 0 FAIL; the child not checked)", "wall_id": 12271, "source": "Wall 12271"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "the run passes Library Check and reaches Accept Models with no pkgLIB2 stop.", "not_shown": "the Library Check passing on a live webhook run.", "source": "Wall 12265, 12271"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "DRAFT, NOT WRITTEN: part 15.0 (the header rule after the Library write rule), manual_0911/w3/em_pairs_661_15.0_draft2.json md5 61128f97cb68b0f9e9949c82bac7db3b; part 16.0 (troubleshooting item 10), manual_0911/w3/em_pairs_661_16.0_draft1.json md5 1fd18bfb182e33b5c9a7c228c721cfec; W1's grade and the operator's press on W3's card are owed; no manual write while a run is live."}$j$::jsonb,
  'read back', $j$[12265, 12266, 12267, 12268, 12269, 12270, 12271, 12273]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "found the fault at the run-start check, built and wrote ASK 661 on the operator's card", "wall_id": 12270}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
